    acl_$srv_resp_t *resp = (acl_$srv_resp_t *)response;         /* A4 */
    uid_t subsys;                     /* (-0x8,A6) */
    uint8_t cur_proj[0x10];           /* (-0x18,A6) */
    uint8_t saved_proj[0x10];         /* (-0x28,A6) */
    uid_t proj_list[ACL_MAX_PROJECTS];/* (-0x68,A6) */
    uint8_t cur_sids[0x28];           /* (-0x90,A6) */
    uint8_t orig_sids[0x28];          /* (-0xB8,A6) */
    acl_$prot_data_t prot;            /* (-0xE8,A6) */
    acl_$prot_data_t funky_prot;      /* (-0x118,A6) */
    uid_t acl_uid;                    /* (-0x120,A6) */
    status_$t restore_status;         /* (-0x12C,A6) */
    status_$t status;                 /* (-0x130,A6) */
    int16_t proj_count;               /* (-0x134,A6) */
    boolean setid;                    /* (-0x136,A6) */
    int8_t create_flag;               /* (-0x138,A6) */
    int8_t image_flag_out;            /* (-0x13C,A6) */
    int16_t create_len;               /* (-0x142,A6) */
    int8_t funky;                     /* D2b */
    int8_t restore_sids;              /* D3b */
    int8_t restore_proj;              /* D2b */
    uint16_t type_bits;               /* D3w */
    void *buf;                        /* D3 */
    acl_$srv_image_req_t *ireq;
    acl_$srv_create_req_t *creq;
    acl_$srv_setids_req_t *sreq;
    acl_$srv_rights_req_t *rreq;
    acl_$srv_set_acl_req_t *areq;
    void *acl_data;                   /* A3 */
    const uint8_t *src;
    int16_t i;

    /* 0x00E495AE-0x00E495C4 */
