        funky = 0;
        create_flag = funky;
        type_bits = (uint16_t)(((uint16_t)(hdr->uid.low >> 16) & ACL_SRV_FUNKY_MASK) >> 4);
        if ((type_bits & ACL_SRV_FUNKY_ANY) != 0) {
            funky = (int8_t)0xFF;
            ACL_$CONVERT_FUNKY_ACL(&hdr->uid, &funky_prot, &acl_uid, &subsys,
                                   &status);
            if ((type_bits & ACL_SRV_FUNKY_CREATE) != 0) {
                create_flag = funky;
            }
        } else {
            acl_uid = hdr->uid;                          /* 0x00E49638 */
            status = status_$ok;
        }
        if (status == status_$ok) {
            ML_$LOCK(ML_LOCK_ACL);
            if (ireq->mode == ACL_SRV_IMAGE_REBUILD) {
                buf = &ACL_$UNWIRED_DATA.image_buf;      /* (0x400,A5) */
                ireq->flag = (int8_t)0xFF;
            } else {
                buf = ARCH_VA_TO_PTR(ireq->buf);
            }
            acl_$image_internal(&acl_uid, ACL_SRV_IMAGE_LEN, ireq->flag, buf,
                                &resp->a.image_len, &prot, &image_flag_out,
                                &status);
            *(acl_$prot_data_t *)(void *)resp->data = prot;   /* 11 longwords */
            if (ireq->mode == ACL_SRV_IMAGE_REBUILD) {
                if (funky < 0) {
                    prot = funky_prot;                   /* 0x00E496B8 */
                }
                if (acl_uid.high == UID_$NIL.high && acl_uid.low == UID_$NIL.low) {
                    ACL_$UNWIRED_DATA.image_buf.type_uid = subsys;
                    ACL_$UNWIRED_DATA.image_buf.subsys_uid = subsys;
                }
                acl_$prim_create_internal(&prot, buf, resp->a.image_len, &subsys,
                                          create_flag, ARCH_VA_TO_PTR(ireq->buf),
                                          &resp->a.image_len, &status);
            }
            ML_$UNLOCK(ML_LOCK_ACL);
        }
        resp->status = status;                            /* 0x00E4972A */
        *reply_len = 0x38;
        return;

    case 0x68:
        /* 0x00E4973A-0x00E49784: ACL_CREATE */
