        acl_data = ARCH_VA_TO_PTR(creq->acl_data);
        acl_uid = creq->acl_uid;
        create_len = (int16_t)((*(int16_t *)((uint8_t *)acl_data + 0xE) << 5) +
                               ACL_SRV_CREATE_HDR_LEN);
        ACL_$PRIM_CREATE(acl_data, &create_len, &hdr->uid, &creq->type,
                         &acl_uid, &resp->status);
        *(uid_t *)(void *)resp->data = acl_uid;
        *reply_len = 0x14;
        return;

    case 0x6C:
        /* 0x00E49788-0x00E497BA: ACL_CHECK_RIGHTS */
        rreq = (acl_$srv_rights_req_t *)request;
        *(uint32_t *)(void *)resp->data =
            acl_$eval_rights(&rreq->sids, rreq->proj, &hdr->uid,
                             rreq->ignore_super, rreq->required_mask,
                             rreq->option_flags, rreq->in_super,
                             rreq->in_subsys, &resp->status);
        *reply_len = 0x10;
        return;

    case 0x6A:
        /* 0x00E497BE-0x00E497F4: ACL_SETIDS */
        sreq = (acl_$srv_setids_req_t *)request;
        acl_$setids(&hdr->uid, (int8_t)0xFF, sreq->sids, sreq->owner_ext,
                    &resp->a.changed, &resp->status);
