        /* 0x00E498AA-0x00E498E2 */
        if (restore_sids < 0) {
            ACL_$SET_RE_ALL_SIDS(orig_sids, cur_sids, saved_proj, cur_proj,
                                 &restore_status);
        }
        if (restore_proj < 0) {
            ACL_$SET_PROJ_LIST(proj_list, &proj_count, &restore_status);
        }
        ACL_$EXIT_SUPER();
